scwin.fn_getUserId = function() {
    return js_emp_no;
};
scwin.fn_searchSubmitDate = function(strKey, strPar) {
    // 발행기관번호,  업무처리번호(목록에서 현재폼 호출시의 매개변수가 지정되고 조회버튼 누른경우 "")
    scwin.strKeyIsurCd = strKey;
    var uri = "/prelistingKosdaq.do?method=listSubmitDate&inputMessageId=PRELISTING_KOSDAQ_SUBMIT_DATE_INOUT&outputMessageId=PRELISTING_KOSDAQ_SUBMIT_DATE_INOUT" + "&ISUR_CD=" + strKey;
    dts_SmtDte.DataID = encodeURI(uri);
    dts_SmtDte.reset();
    var strCbd = "";
    for (var i = 1; i <= dts_SmtDte.CountRow; i++) {

	//----W-Craft WebSquare 변환 확인: NameString----//

	//----W-Craft WebSquare 변환 확인: NameValue----//
        strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_SmtDte.NameValue(i, "BZ_PROCS_NO") + "^" + dts_SmtDte.NameString(i, "BILL_SUBMIT_DD_DISP");
    }
    cmb_BillSubmitDd.CBData = strCbd;

	//----W-Craft WebSquare 변환 확인: IndexOfColumn----//
    cmb_BillSubmitDd.Index = (strPar == "" ? 0 : cmb_BillSubmitDd.Index = cmb_BillSubmitDd.IndexOfColumn("BZ_PROCS_NO", strPar));
    if (cmb_BillSubmitDd.Index > -1) {
        scwin.fn_search(cmb_BillSubmitDd.BindColVal);
    } else {
        scwin.fn_search("");
    }
};
scwin.fn_searchCode = function() {
    /*
    업종(세분류)-일반사항
    X-팝업-상장주선인-일반사항
    X-팝업-심사자-일반사항
    01295-기업구분-일반사항-PRELM_INVSTG_COM_TP_CD-cmb_PrelmInvstgComTpCd
    01179-감사의견-일반사항-AUDT_OPIN_TP_CD-cmb_AudtOpin
    00740-심사청구구분코드-일반사항-INVSTG_CLM_TP_CD-cmb_InvstgClmTpCd
    X-00672-기업규모구분-일반사항-radio button이므로 제외
    국가코드-일반사항
    00443-통화ISO코드-일반사항-CURR_ISO_CD-cmb_CurrIsoCd
    01291-벤처지정사유-일반사항-VENT_DESIGN_RSN_CD-cmb_VentDesignRsnCd
    00685-명의개서대행기관-일반사항-TRANSSTK_AGNT_CD-cmb_TransstkAgntCd
    00826-투자변동사항-벤처캐피탈,기관투자가-INVST_CHG_TP_CD-cmb_VcInvstChgTpCd, cmb_InstInvstChgTpCd
    X-주식종류-벤처캐피탈,기관투자가-텍스트
    00123-발행구분-CB,BW,회사채-ISU_TP_CD-1:국내공모,2:국내사모,3:해외공모,4:해외사모,5:공모-cmb_IsuTpCd
    00835-행사구분-BW-EXER_PAY_TP_CD-1:채권대용납입,2:주금납입-cmb_ExerPayTpCd
    00945-대상자구분-보호예수-PRTDEPO_PRN_TP_CD-1:최대주주,2:특수관계인(영업양수시 비공개법인 포함),3:벤처금융,4:기관투자가,5:유상증자한도초과자-cmb_PrtdepoPrnTpCd
    01244-보호예수대상종류-보호예수-PRTDEPO_OBJ_KIND_CD-1:보통주,2:우선주,3:주식관련사채-cmb_PrtdepoObjKindCd
    00699-보호예수대상구분코드-보호예수-PRTDEPO_OBJ_TP_CD-1:전환우선주,2:상환우선주,3:상환전환우선주,4:전환사채,5:신주인수권부사채,6:기타-cmb_PrtdepoObjTpCd
    */
    var arrCid = [{
        cid: "PRELM_INVSTG_COM_TP_CD",
        cnm: "cmb_PrelmInvstgComTpCd"
    }, {
        cid: "AUDT_OPIN_TP_CD",
        cnm: "cmb_AudtOpin"
    }, {
        cid: "INVSTG_CLM_TP_CD",
        cnm: "cmb_InvstgClmTpCd"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_CurrIsoCd"
    }, {
        cid: "VENT_DESIGN_RSN_CD",
        cnm: "cmb_VentDesignRsnCd"
    }, {
        cid: "TRANSSTK_AGNT_CD",
        cnm: "cmb_TransstkAgntCd"
    }, {
        cid: "INVST_CHG_TP_CD",
        cnm: "cmb_VcInvstChgTpCd"
    }, {
        cid: "INVST_CHG_TP_CD",
        cnm: "cmb_InstInvstChgTpCd"
    }, {
        cid: "ISU_TP_CD",
        cnm: "cmb_CbIsuTpCd"
    }, {
        cid: "ISU_TP_CD",
        cnm: "cmb_BwIsuTpCd"
    }, {
        cid: "ISU_TP_CD",
        cnm: "cmb_BndIsuTpCd"
    }, {
        cid: "EXER_PAY_TP_CD",
        cnm: "cmb_BwExerPayTpCd"
    }, {
        cid: "PRTDEPO_PRN_TP_CD",
        cnm: "cmb_PrtdepoPrnTpCd"
    }, {
        cid: "PRTDEPO_OBJ_KIND_CD",
        cnm: "cmb_PrtdepoObjKindCd"
    }, {
        cid: "PRTDEPO_OBJ_TP_CD",
        cnm: "cmb_PrtdepoObjTpCd"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='PRELM_INVSTG_COM_TP_CD','AUDT_OPIN_TP_CD','INVSTG_CLM_TP_CD','CURR_ISO_CD','VENT_DESIGN_RSN_CD' ,'TRANSSTK_AGNT_CD','INVST_CHG_TP_CD' ,'ISU_TP_CD','EXER_PAY_TP_CD','PRTDEPO_PRN_TP_CD','PRTDEPO_OBJ_KIND_CD','PRTDEPO_OBJ_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < com.wconv.length(arrCid); i++) {

	//----W-Craft WebSquare 변환 확인: getElementById----//
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.CountRow; j++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
            if (dts_Cod.NameValue(j, "CD_ENG_NM") == arrCid[i].cid) {

	//----W-Craft WebSquare 변환 확인: NameString----//
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.NameString(j, "VALUE") + "^" + com.wconv.replace(/,/g, "','");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_searchReqInf = function(strKey) {
    var uri = "/prelistingKosdaq.do?method=searchReqInf&inputMessageId=PRELISTING_KOSDAQ_REQINF_INOUT&outputMessageId=PRELISTING_KOSDAQ_REQINF_INOUT&BZ_PROCS_NO=" + strKey;
    dts_ReqInf.DataID = encodeURI(uri);
    dts_ReqInf.reset();
    /*

	//----W-Craft WebSquare 변환 확인: NameString----//
    rdo_ClmDtlWebDpYn.CodeValue			= dts_ReqInf.NameString(1, "CLM_DTL_WEB_DP_YN");

	//----W-Craft WebSquare 변환 확인: NameString----//
    med_ClmDtlWebDpDd.Text 				= dts_ReqInf.NameString(1, "CLM_DTL_WEB_DP_DD");
    */

	//----W-Craft WebSquare 변환 확인: NameString----//
    chk_PrelmInvstgRevwCompltYn.checked = (dts_ReqInf.NameString(1, "PRELM_INVSTG_REVW_COMPLT_YN") == "Y");

	//----W-Craft WebSquare 변환 확인: NameString----//
    if (dts_ReqInf.NameString(1, "CLM_DTL_WEB_DP_DD") == "") {
        var ds = cmb_BillSubmitDd.text.replace(/\-/g, "");
        var y = com.wconv.parseInt(ds.substring(0, 4));
        var m = ds.substring(4, 6);
        m = com.wconv.parseInt((m.substring(0, 1) == "0" ? m.substring(1, 2) : m));
        var d = ds.substring(6, 8);
        d = com.wconv.parseInt((d.substring(0, 1) == "0" ? d.substring(1, 2) : d));
        do {
            d = d + 1;
            td = new Date(y, m - 1, d);
        } while ((com.wconv.getDay() == 0) || (com.wconv.getDay() == 6));
        med_ClmDtlWebDpDd.setValue(com.wconv.toString() + (m > 9 ? "" : "0") + com.wconv.toString() + (d > 9 ? "" : "0") + com.wconv.toString());
    }
    var s = "";
    for (i = 1; i <= dts_ReqInf.CountColumn; i++) {

	//----W-Craft WebSquare 변환 확인: ColumnString----//

	//----W-Craft WebSquare 변환 확인: ColumnID----//
        s = s + "\n" + dts_ReqInf.ColumnID(i) + ":" + dts_ReqInf.ColumnString(1, i);
    }
    // alert( "ReqInf is :" + s );
    log.setValue(log.getValue() + "\n" + s);
};
scwin.fn_search = function(strKey) {
    // 업무처리번호가 키값이다.

    var recSvc = arrSvc[tab.ActiveIndex - 1];

	//----W-Craft WebSquare 변환 확인: getElementById----//
    var dts_Tgt = document.getElementById(recSvc.dst);

    //if (strKey != strKeyBzProcsNo) {
    scwin.strKeyBzProcsNo = strKey;
    scwin.fn_searchReqInf(scwin.strKeyBzProcsNo);
    //}

    if (dts_Tgt != undefined) {
        var uri = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=" + recSvc.fndMtd + "&inputMessageId=" + recSvc.hdr + "&outputMessageId=" + recSvc.hdr + "&BZ_PROCS_NO=" + scwin.strKeyBzProcsNo;
        dts_Tgt.DataID = encodeURI(uri);
        dts_Tgt.reset();
    }
};




// 저장, 접수 등의 처리
scwin.fn_save = function() {
    //2009.05.22 시스템 담당자(999999)도  수정이 안되도록 체크
    //alert("fn_getUserId()-->"+fn_getUserId());
    if (scwin.fn_getUserId() == "999999") {
        alert("해당 부서만 저장이 가능합니다.");
        return false;
    }

    //2009.05.12 예비심사처리절차 등록 여부			
    /*

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var cnt = dts_EntInf.NameValue(1, "STAT_CNT");
    alert("cnt1111111-->"+cnt);
    if(cnt == "0"){
    	alert("예비심사절차등록이 누락되었습니다. 절차등록을 해주시기 바랍니다.");
    	return false;
    }			
    */

    //2009.05.26 예비심사처리절차 등록 여부
    if (scwin.fn_searchStatCnt(scwin.strKeyBzProcsNo)) {
        //alert("strKeyBzProcsNo-->"+strKeyBzProcsNo);
        return false;
    }
    var recSvc = arrSvc[tab.ActiveIndex - 1];

	//----W-Craft WebSquare 변환 확인: getElementById----//
    var dts_Tgt = document.getElementById(recSvc.dst);
    if (dts_Tgt != undefined) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//
        /*ORG SRC: dts_ReqInf.NameString(1, "PRELM_INVSTG_REVW_COMPLT_YN") = (chk_PrelmInvstgRevwCompltYn.checked ? "Y" : "N");*/

	//----W-Craft WebSquare 변환 확인: NameString----//
        X = (chk_PrelmInvstgRevwCompltYn.checked ? "Y" : "N"); /*ORG SRC: dts_ReqInf.NameString(1, "LST_CHG_EMP_NO") = fn_getUserId();*/ X = scwin.fn_getUserId();
        if ((dts_ReqInf.CountRow == 0) || ((!dts_Tgt.IsUpdated) && (!dts_ReqInf.IsUpdated))) {
            alert(scwin.MSG_NO_UPDT);
            return;
        }

	//----W-Craft WebSquare 변환 확인: NameString----//
        if (dts_ReqInf.NameString(1, "ACPT_YN") != "Y") {
            alert(scwin.MSG_NO_ACPT);
            return;
        }
        // checkbox의 경우 'Y', 'N'값으로 bind를 할 수 없으므로, 수동으로 반영한다. 그 외의 공통항목(웹반영여부, 웹반영일)은 binder를 이용

        if (dts_Tgt == dts_EntInf) {
            // 기업정보에 해당하는 checkbox

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//
            /*ORG SRC: dts_EntInf.NameString(1, "VENTSPECLCS_APPL_YN") = (chk_VentspeclcsApplYn.checked ? "Y" : "N"); // 벤처특례적용여부*/
            X = (chk_VentspeclcsApplYn.checked ? "Y" : "N"); // 벤처특례적용여부

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//
            /*ORG SRC: dts_EntInf.NameString(1, "VENTSPECLCS_PROG_YYS_YN") = (chk_VentspeclcsProgYysYn.checked ? "Y" : "N"); // 벤처특례경과년수여부*/
            X = (chk_VentspeclcsProgYysYn.checked ? "Y" : "N"); // 벤처특례경과년수여부

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//
            /*ORG SRC: dts_EntInf.NameString(1, "VENTSPECLCS_CAP_YN") = (dts_EntInf.NameString(1, "VENTSPECLCS_CAP_YN") == "" ? "N" : dts_EntInf.NameString(1, "VENTSPECLCS_CAP_YN")); // 벤처특례자본금여부*/

	//----W-Craft WebSquare 변환 확인: NameString----//
            X = (dts_EntInf.NameString(1, "VENTSPECLCS_CAP_YN") == "" ? "N" : dts_EntInf.NameString(1, "VENTSPECLCS_CAP_YN")); // 벤처특례자본금여부

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//
            /*ORG SRC: dts_EntInf.NameString(1, "VENTSPECLCS_ROE_YN") = (dts_EntInf.NameString(1, "VENTSPECLCS_ROE_YN") == "" ? "N" : dts_EntInf.NameString(1, "VENTSPECLCS_ROE_YN")); // 벤처특례ROE여부*/

	//----W-Craft WebSquare 변환 확인: NameString----//
            X = (dts_EntInf.NameString(1, "VENTSPECLCS_ROE_YN") == "" ? "N" : dts_EntInf.NameString(1, "VENTSPECLCS_ROE_YN")); // 벤처특례ROE여부

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//
            /*ORG SRC: dts_EntInf.NameString(1, "VENTSPECLCS_DEBT_AMT_RTO_YN") = (dts_EntInf.NameString(1, "VENTSPECLCS_DEBT_AMT_RTO_YN") == "" ? "N" : dts_EntInf.NameString(1, "VENTSPECLCS_DEBT_AMT_RTO_YN")); // 벤처특례부채금액비율여부*/

	//----W-Craft WebSquare 변환 확인: NameString----//
            X = (dts_EntInf.NameString(1, "VENTSPECLCS_DEBT_AMT_RTO_YN") == "" ? "N" : dts_EntInf.NameString(1, "VENTSPECLCS_DEBT_AMT_RTO_YN")); // 벤처특례부채금액비율여부

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
