scwin.getRgtIdxTop = function(idx) {
    return Math.ceil(com.wconv.length(accMapTop) / 2) + idx;
};
scwin.getRgtIdxBtm = function(idx) {
    return Math.ceil(com.wconv.length(accMapBtm) / 2) + idx;
};
scwin.getString = function(s, rpt) {
    var ts = s;
    for (var i = 1; i < rpt; i++) {
        s += ts;
    }
    return s;
};
scwin.fn_wrtGrdFinTop = function() {
    // 1row로 구성된 dts_Fin의 내용을 2계정이 1row로 구성된 dts_FinBuf로 변환하고, 사용자에게 grid를 통해서 표시한다.
    var i = 0,
        j = 0,
        curRow = 0;
    var bufDid = grd_FinTop.DataID; // grid의 움직임을 방지하기 위하여 DataID를 임시로 보관, 작업후 원상복구
    grd_FinTop.DataID = "";
    dts_FinBuf.ClearData();
    for (i = 0; i < Math.ceil(com.wconv.length(accMapTop) / 2); i++) {
        dts_FinBuf.insertRow();
        // 계정과목을 write

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameValue----//
        curRow = dts_FinBuf.CountRow; /*ORG SRC: dts_FinBuf.NameValue(curRow, "ACC_NM_1") = getString(" ", Math.max(accMapTop[i].colDpt - 1, 0) * 4) +*/ X = scwin.getString(" ", Math.max(accMapTop[i].colDpt - 1, 0) * 4) + accMapTop[i].colCap;
        /*

	//----W-Craft WebSquare 변환 확인: NameValue----//
        dts_FinBuf.NameValue(curRow, "ACC_NM_2") = getString(" ", Math.max(accMapTop[i].colDpt - 1, 0) * 4) + 
        										   accMapTop[getRgtIdxTop(i)].colCap;
        */

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameValue----//
        /*ORG SRC: dts_FinBuf.NameValue(curRow, "ACC_NM_2") = getString(" ", Math.max(accMapTop[getRgtIdxTop(i)].colDpt - 1, 0) * 4) +*/
        X = scwin.getString(" ", Math.max(accMapTop[scwin.getRgtIdxTop(i)].colDpt - 1, 0) * 4) + accMapTop[scwin.getRgtIdxTop(i)].colCap;
        // 계정값을 write
        for (j = 0; j < com.wconv.length(accIdxTop); j++) {
            // 6개의 반기, 전기, 전전기컬럼에 표시
            // 표시컬럼이 우측일 경우 array의 절반크기만큼 추가된 인덱스로 배열을 참조해야 한다.

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: ColumnValue----//

	//----W-Craft WebSquare 변환 확인: NameValue----//
            arrIdx = (accIdxTop[j].colIdx > Math.ceil(dts_FinBuf.CountColumn / 2) ? scwin.getRgtIdxTop(i) : i); /*ORG SRC: dts_FinBuf.ColumnValue(curRow, accIdxTop[j].colIdx) = dts_Fin.NameValue(1, // dts_Fin에는 1row만 존재한다.*/ X = dts_Fin.NameValue(1, // dts_Fin에는 1row만 존재한다.
                accIdxTop[j].colHdr + "_" + accMapTop[arrIdx].colFtr);
        }
    }
    dts_FinBuf.RowPosition = 1;
    grd_FinTop.DataID = bufDid; // grid에 dataset 내용 표시
};
