scwin.fn_getPanDisabled = function(p) {
    for (var i = 0; i < com.wconv.length(scwin.arrPanDisabled); i++) {
        // array에 보관되어있던 해당panel의 disabled property 검색
        if (scwin.arrPanDisabled[i].panel == p) {
            return scwin.arrPanDisabled[i].disabled;
        }
    }
    return undefined;
};

	//----W-Craft WebSquare 변환 확인: fn_setPanReadOnly----//
scwin.fn_setPanReadOnlyOnLoad = function(d, p) {
    // o: dataset, p: panel

    var oldVal = scwin.fn_getPanDisabled(p);
    if (d == undefined) {
        if ((oldVal == undefined) || !oldVal) {
            //  과거 해당panel의 disabled 상태가 없거나, 예전에는 false일 경우(수정가능상태)
            scwin.arrPanDisabled[scwin.arrPanDisabled.length] = {
                panel: p,
                disabled: true
            };

	//----W-Craft WebSquare 변환 확인: fn_setPanReadOnly----//
            fn_setPanReadOnly(p);
        }
        scwin.panDisabled = true;
    } else {
        if (d.CountRow == 0) {

	//----W-Craft WebSquare 변환 확인: fn_setPanReadOnly----//
            fn_setPanReadOnly(p);
            /*
            if ((oldVal == undefined) || !oldVal) { //  과거 해당panel의 disabled 상태가 없거나, 예전에는 false일 경우(수정가능상태)
            	arrPanDisabled[arrPanDisabled.length] = {panel: p, disabled: true};

	//----W-Craft WebSquare 변환 확인: fn_setPanReadOnly----//
            	fn_setPanReadOnly(p);
            }
            */
            scwin.panDisabled = true;
            keyDisabled = ((d == dts_EntInf) || (d == dts_Fin) || (d == dts_Stk));
        } else {
            if ((oldVal == undefined) || oldVal) {
                //  과거 해당panel의 disabled 상태가 없거나, 예전에는 false일 경우(수정가능상태)
                scwin.arrPanDisabled[scwin.arrPanDisabled.length] = {
                    panel: p,
                    disabled: false
                };

	//----W-Craft WebSquare 변환 확인: fn_setPanWritable----//

	//----W-Craft WebSquare 변환 확인: fn_setPanWritable2----//
                fn_setPanWritable2(p, scwin.fn_getExcCtrs(p));
            }
            scwin.panDisabled = false;
            keyDisabled = !((d == dts_EntInf) || (d == dts_Fin) || (d == dts_Stk));
        }
    }
};

	//----W-Craft WebSquare 변환 확인: fn_setPanWritable----//
scwin.fn_setPanWritableOnAdd = function(p) {
    // o: dataset, p: panel
    var oldVal = scwin.fn_getPanDisabled(p);
    if ((oldVal == undefined) || oldVal) {
        //  과거 해당panel의 disabled 상태가 없거나, 예전에는 false일 경우(수정가능상태)
        scwin.arrPanDisabled[scwin.arrPanDisabled.length] = {
            panel: p,
            disabled: false
        };

	//----W-Craft WebSquare 변환 확인: fn_setPanWritable----//
        fn_setPanWritable(p);
    }
    scwin.panDisabled = false;
};
