scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = com.wconv.split("?");

	//----W-Craft WebSquare 변환 확인: Provider----//
    return (com.wconv.length(arr) >= 1 ? frame.Provider("../" + arr[1]) : undefined);
};
